import { AuthController } from "@/modules/auth/controller";
import { cookies } from "next/headers";

const controller =
new AuthController();


export async function POST(
 request:Request
){

try {


const body =
await request.json();



const result =
await controller.login(
 body.email,
 body.password
);



const cookieStore =
await cookies();



cookieStore.set(
 "token",
 result.token,
 {
  httpOnly:true,
  secure:false,
  sameSite:"lax",
  maxAge:60 * 60 * 24 * 7,
  path:"/"
 }
);



return Response.json({

 success:true,

 data:{
  user:result.user
 }

});


}
catch(error){

return Response.json(
{
 success:false,
 message:"Invalid credentials"
},
{
 status:401
}
);

}

}